<section class="page-heading"><div><h1><?= e($sale['invoice_number']) ?></h1><p><?= e($sale['document_type']) ?> · <?= $sale['cancellation_id']?'Cancelled':'Posted' ?></p></div><div class="product-actions"><?php if(can($user,'pos.access') && can($user,'sales.create')): ?><a class="button button-primary" href="<?= e(url('/pos')) ?>">New sale</a><?php endif; ?><?php if(can($user,'sales.view')): ?><a class="button" href="<?= e(url('/sales')) ?>">Sales history</a><?php endif; ?><?php if(can($user,'sales.reprint')): ?><a class="button" href="<?= e(url('/sales/print')) ?>&amp;id=<?= (int)$sale['id'] ?>&amp;format=a4" target="_blank" rel="noopener">Print A4</a><a class="button" href="<?= e(url('/sales/print')) ?>&amp;id=<?= (int)$sale['id'] ?>&amp;format=thermal" target="_blank" rel="noopener">Print 80mm</a><?php endif; ?></div></section>
<?php if($notice): ?><div class="notice" role="status"><?= e($notice) ?></div><?php endif; ?><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="surface product-section"><?php $format='a4';require __DIR__.'/document.php'; ?></div>
<?php if(can($user,'sales.payments')): ?><section class="surface product-section sales-payment-history"><h2>Payment details</h2><?php if(!$sale['payments']): ?><p>No payments recorded. This is a credit sale.</p><?php endif; ?><div class="table-scroll"><table><thead><tr><th>Date / Recorded by</th><th>Method</th><th>Received</th><th>Change</th><th>Applied / Refunded</th><th>Reference</th></tr></thead><tbody><?php foreach($sale['payments'] as $p): ?><tr><td><?= e(local_datetime($p['payment_date'])) ?><small><?= e($p['recorder']) ?></small></td><td><?= e(strtoupper($p['method'])) ?></td><td><?= money($p['received']) ?></td><td><?= money($p['change_returned']) ?></td><td><?= money($p['amount']) ?></td><td><?= e($p['reference']??'—') ?><?= $p['reverses_payment_id']?' · Reverses payment #'.(int)$p['reverses_payment_id']:'' ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if(can($user,'inventory.movements') && $sale['items']): ?><section class="surface product-section"><h2>Linked stock movements</h2><?php foreach($sale['items'] as $item): ?><p><?= e($item['line']['name']) ?>: <a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$item['movement_id'] ?>">Sale #<?= (int)$item['movement_id'] ?></a><?php if($item['reversal_id']): ?> · <a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$item['reversal_id'] ?>">Reversal #<?= (int)$item['reversal_id'] ?></a><?php endif; ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if(can($user,'sales.cancel') && !$sale['cancellation_id']): ?><section class="surface product-section"><p class="subtle-text">Posted invoices cannot be edited or deleted. Cancellation restores every sold quantity and records payment reversals.</p><button class="button" type="button" data-open-cancellation>Cancel invoice</button></section><dialog class="sales-dialog" id="sales-cancellation-dialog"><div class="pos-section-heading"><h2>Cancel <?= e($sale['invoice_number']) ?></h2><button class="icon-button" type="button" data-close-dialog aria-label="Close cancellation">×</button></div><form method="post" action="<?= e(url('/sales/cancel')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$sale['id'] ?>"><label>Cancellation reason *<textarea name="reason" required maxlength="500" rows="3"></textarea></label><p>Cancel product and labour revenue, restore sold stock where applicable, and reverse <?= money($sale['amount_paid']) ?> of applied payments. Outstanding credit will be cancelled. This records refunds; it does not send money.</p><label class="check-label"><input type="checkbox" name="confirmed" value="1" required> <?= $sale['items']?'All sold items are in the shop and can be restored to stock.':'I confirm cancellation of this invoice.' ?></label><label class="check-label"><input type="checkbox" name="refund_confirmed" value="1" required> I have returned the applied payments using the original methods, or no payment was collected.</label><div class="product-actions"><button class="button" type="button" data-close-dialog>Keep invoice</button><button class="button button-primary">Confirm cancellation</button></div></form></dialog><?php endif; ?>
